CREATE OR REPLACE FUNCTION calculate_match_success_rate(user_id_param INT, min_date DATE)
RETURNS NUMERIC AS $$
DECLARE
  total_matches INT;
  successful_matches INT;
BEGIN
  SELECT COUNT(*)
  INTO total_matches
  FROM matches
  WHERE (user1_id = user_id_param OR user2_id = user_id_param)
    AND match_date >= min_date;

  IF total_matches = 0 THEN
    RETURN 0.00;
  END IF;

  SELECT COUNT(DISTINCT m.match_id)
  INTO successful_matches
  FROM matches m
  WHERE (m.user1_id = user_id_param OR m.user2_id = user_id_param)
    AND m.match_date >= min_date
    AND EXISTS (
      SELECT 1 FROM messages msg1
      WHERE msg1.match_id = m.match_id
        AND msg1.sender_id = user_id_param
    )
    AND EXISTS (
      SELECT 1 FROM messages msg2
      WHERE msg2.match_id = m.match_id
        AND msg2.recipient_id = user_id_param
        AND msg2.sender_id != user_id_param
    );

  RETURN ROUND((successful_matches::NUMERIC / total_matches::NUMERIC) * 100, 2);
END;
$$ LANGUAGE plpgsql;

SELECT calculate_match_success_rate(101, '2024-01-01') AS result;
